{
  "book_code": "2ES",
  "verses": [
    {
      "chapter": 10,
      "text_ar": "أو أن حسي مخدوع، أم أن نفسي في حلم؟",
      "verse": 36
    },
    {
      "chapter": 10,
      "text_ar": "والآن لذلك أرجوك أن تفسر لعبدك ما تعنيه هذه الرؤيا.",
      "verse": 37
    },
    {
      "chapter": 10,
      "text_ar": "فأجابني: استمع إلي، وسأعلمك، وأخبرك بالأمور التي تخاف منها، لأن العلي كشف لك أموراً سرية كثيرة.",
      "verse": 38
    },
    {
      "chapter": 10,
      "text_ar": "لقد رأى أن طريقك بار، لأنك تأسف باستمرار على شعبك، وتنوح نوحاً عظيماً على صهيون.",
      "verse": 39
    },
    {
      "chapter": 10,
      "text_ar": "هذا إذن هو معنى الرؤيا.",
      "verse": 40
    }
  ]
}
